import{_ as a,a as s}from"./chunks/about-dialog.BbBZEu07.js";import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"Install & Run","description":"KomaYomi runs either as a browser app backed by a local Node server or as an Electron desktop window. Both use the same server code and the same data…","frontmatter":{"description":"KomaYomi runs either as a browser app backed by a local Node server or as an Electron desktop window. Both use the same server code and the same data…"},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1794778665000}'),r={name:"guide/installation.md"};function d(l,e,p,c,h,u){return i(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="install-run" tabindex="-1">Install &amp; Run <a class="header-anchor" href="#install-run" aria-label="Permalink to &quot;Install &amp; Run&quot;">​</a></h1><p>KomaYomi runs either as a <strong>browser app backed by a local Node server</strong> or as an <strong>Electron desktop window</strong>. Both use the same server code and the same data directory.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>You want the app running on your own machine, reading your own folders, with no account and no upload. This page gets you from a fresh clone to a first page open, and explains how the desktop package differs from the browser dev server.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Node.js 20 or newer</strong> (the server bundle targets Node 20; the repository is developed against Node 22+).</li><li>npm (bundled with Node).</li><li>Optional: Electron dependencies are installed as part of <code>npm install</code>.</li></ul><p>There is no hosted service and no account. The app listens on <code>127.0.0.1</code> only.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="run-in-development" tabindex="-1">Run in development <a class="header-anchor" href="#run-in-development" aria-label="Permalink to &quot;Run in development&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>This starts Vite on <code>http://127.0.0.1:5173</code> (the port may shift if 5173 is busy). The API is served by a Vite middleware plugin, so there is no second process to start.</p><h2 id="run-as-a-desktop-app" tabindex="-1">Run as a desktop app <a class="header-anchor" href="#run-as-a-desktop-app" aria-label="Permalink to &quot;Run as a desktop app&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p>This command does three things:</p><ol><li><code>npm run build</code> — type-checks and builds the frontend into <code>dist/</code>.</li><li><code>npm run server:build</code> — bundles the server into <code>dist-server/app.mjs</code> with esbuild.</li><li><code>electron .</code> — opens a window that loads the bundled static files from a local HTTP server.</li></ol><p>Desktop data directory:</p><ul><li>Running from source (<code>npm run desktop</code>), it uses the repository folder, keeping <code>raw/</code>, <code>data/</code> and <code>exports/</code> next to the code.</li><li>A packaged build defaults to a <code>library</code> folder inside Electron&#39;s <code>userData</code> directory and asks you to choose a folder on first launch.</li><li><code>Ctrl+Shift+D</code> switches the data directory (a restart is required).</li><li>The environment variable <code>MANGA_DATA_DIR</code> overrides the data directory.</li><li><code>MANGA_PORT</code> fixes the internal port; otherwise a free port is chosen.</li></ul><h2 id="package-a-desktop-build" tabindex="-1">Package a desktop build <a class="header-anchor" href="#package-a-desktop-build" aria-label="Permalink to &quot;Package a desktop build&quot;">​</a></h2><p>The repository ships <code>electron-builder.yml</code> and two packaging scripts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:win</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Windows x64: NSIS installer + portable .exe in release/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:dir</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # unpacked app in release/, useful for a quick smoke test</span></span></code></pre></div><p><code>dist:win</code> builds the frontend and the bundled server first, then runs electron-builder with both the <code>nsis</code> and <code>portable</code> targets. Artifacts are named <code>KomaYomi-&lt;version&gt;-&lt;arch&gt;.exe</code> and <code>KomaYomi-&lt;version&gt;-portable.exe</code>.</p><p>What the package contains:</p><ul><li><code>dist/</code>, <code>dist-server/</code>, <code>electron/</code> and <code>package.json</code> only — no <code>node_modules</code> are shipped.</li><li><code>raw/</code>, <code>data/</code> and <code>exports/</code> are <strong>not</strong> bundled. A packaged build asks for a library folder on first launch and remembers it.</li></ul><p>Current limitations:</p><ul><li>Windows x64 is the only configured target; there is no macOS or Linux packaging.</li><li>The installer is unsigned, so Windows SmartScreen may warn on first launch.</li><li>Packaging has not yet been produced end-to-end in this repository; treat the first <code>npm run dist:win</code> output as <strong>unverified</strong> until you smoke-test it.</li><li>There is no auto-update channel.</li></ul><figure class="shot"><img src="`+a+`" alt="First launch with an empty library: the sidebar shows Add manga and the main area shows a four-step tour"><figcaption>First launch with an empty library. ＋ Add manga is the way in; the four cards outline the workflow.</figcaption></figure><h2 id="build-outputs" tabindex="-1">Build outputs <a class="header-anchor" href="#build-outputs" aria-label="Permalink to &quot;Build outputs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Output</th><th>Purpose</th></tr></thead><tbody><tr><td><code>npm run build</code></td><td><code>dist/</code></td><td>Static frontend.</td></tr><tr><td><code>npm run server:build</code></td><td><code>dist-server/app.mjs</code></td><td>Bundled Node server used by Electron.</td></tr><tr><td><code>npm run dist:dir</code></td><td><code>release/</code></td><td>Unpacked Electron app for smoke testing.</td></tr><tr><td><code>npm run dist:win</code></td><td><code>release/</code></td><td>Windows x64 NSIS installer and portable <code>.exe</code> (not yet verified).</td></tr><tr><td><code>npm run preview</code></td><td>—</td><td>Serves the built frontend with Vite preview. The API middleware is a dev-server feature; use the desktop app or <code>npm run dev</code> for API access.</td></tr><tr><td><code>npm run typecheck</code></td><td>—</td><td>TypeScript project check.</td></tr></tbody></table><h2 id="data-directory-layout" tabindex="-1">Data directory layout <a class="header-anchor" href="#data-directory-layout" aria-label="Permalink to &quot;Data directory layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/                       # your images (gitignored)</span></span>
<span class="line"><span>  &lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</span></span>
<span class="line"><span>data/</span></span>
<span class="line"><span>  pages/&lt;volume&gt;/&lt;chapter&gt;/0.json     # one page JSON, 0-based index</span></span>
<span class="line"><span>  templates/                          # panel templates and export templates</span></span>
<span class="line"><span>  presets/                            # alignment presets</span></span>
<span class="line"><span>  layouts/*.json                      # declarative layout templates</span></span>
<span class="line"><span>  library.json                        # manual language-directory mapping</span></span>
<span class="line"><span>  cache/thumbs/                       # thumbnail cache (safe to delete)</span></span>
<span class="line"><span>  backups/                            # project import backups (gitignored)</span></span>
<span class="line"><span>exports/                   # generated HTML, PNG, backups, .mnproj (gitignored)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><code>npm run dev</code> serves images through <code>/raw/...</code> and generated files through <code>/exports/...</code>; neither folder is exposed as a static directory listing.</p><h2 id="ports-and-hosts" tabindex="-1">Ports and hosts <a class="header-anchor" href="#ports-and-hosts" aria-label="Permalink to &quot;Ports and hosts&quot;">​</a></h2><ul><li>Development UI: <code>127.0.0.1:5173</code>.</li><li>Documentation site (this site): <code>127.0.0.1:5174</code> when started from <code>docs/</code>.</li><li>The Electron window talks to an ephemeral localhost port.</li></ul><h2 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First run&quot;">​</a></h2><ol><li>Put at least one volume under <code>raw/</code> following <code>raw/&lt;volume&gt;/&lt;ja|zh|en&gt;/&lt;chapter&gt;/&lt;pages&gt;</code>.</li><li>Open the app. The sidebar lists volumes and chapters.</li><li>Select a page. On first open the page is automatically detected and saved.</li><li>If a language folder is not recognized, open the volume settings and map directories manually.</li><li>Click the <strong>About</strong> button in the top bar to confirm the version and the active data directory before reporting a problem.</li></ol><figure class="shot"><img src="`+s+`" alt="About dialog with the KomaYomi version, build information and data directory path"><figcaption>The About dialog. The version and data directory are the first two facts to include in a bug report.</figcaption></figure><p>See <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a> for naming rules and the language aliases the scanner accepts.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Port 5173 is busy.</strong> Vite picks the next free port; read the URL printed in the terminal instead of assuming 5173.</li><li><strong>The sidebar is empty.</strong> There is no volume under <code>raw/</code>, or the folder names were not recognized. See <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a>.</li><li><strong>A packaged build asks for a folder.</strong> That is expected: packages do not bundle <code>raw/</code>, <code>data/</code> or <code>exports/</code>.</li><li><strong>Changes do not appear in the desktop window.</strong> Restart after switching the data directory with <code>Ctrl+Shift+D</code>; the switch is not live.</li><li><strong><code>npm run preview</code> has no API.</strong> The API middleware exists only in the dev server and the desktop app, so pages cannot load images there.</li><li><strong><code>dist:win</code> is unverified.</strong> Treat the first packaging run as a smoke test; report what the installer does on a clean machine.</li></ul><h2 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h2><p>The docs live in <code>docs/</code> with their own dependencies:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://127.0.0.1:5174</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # static output in docs/.vitepress/dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # preview the production build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>From the repository root you can also use <code>npm --prefix docs run docs:dev</code>.</p>`,45)])])}const k=t(r,[["render",d]]);export{b as __pageData,k as default};
